use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

/// Rate limiter for API endpoints using token bucket algorithm.
/// Each user gets a bucket with configurable capacity and refill rate.

const MAX_TOKENS: u32 = 100;
const REFILL_RATE: u32 = 10; // tokens per second
const BURST_MULTIPLIER: u32 = 3;

#[derive(Debug, Clone)]
pub struct TokenBucket {
    tokens: u32,
    last_refill: u64,
    capacity: u32,
    tier: UserTier,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum UserTier {
    Free,
    Premium,
    Enterprise,
}

impl UserTier {
    fn capacity_multiplier(&self) -> u32 {
        match self {
            UserTier::Free => 1,
            UserTier::Premium => 2,
            UserTier::Enterprise => BURST_MULTIPLIER,
        }
    }
}

#[derive(Debug)]
pub struct RateLimiter {
    buckets: Mutex<HashMap<String, TokenBucket>>,
    global_limit: u32,
    global_consumed: Mutex<u32>,
}

#[derive(Debug, PartialEq)]
pub enum RateLimitResult {
    Allowed { remaining: u32 },
    Denied { retry_after_ms: u64 },
}

#[derive(Debug)]
pub struct RequestContext {
    pub user_id: String,
    pub endpoint: String,
    pub cost: u32,
    pub tier: UserTier,
    pub timestamp: u64,
}

impl RateLimiter {
    pub fn new(global_limit: u32) -> Self {
        RateLimiter {
            buckets: Mutex::new(HashMap::new()),
            global_limit,
            global_consumed: Mutex::new(0),
        }
    }

    /// Calculate how many tokens to add based on elapsed time
    fn calculate_refill(bucket: &TokenBucket, now: u64) -> u32 {
        let elapsed = now.saturating_sub(bucket.last_refill);
        let new_tokens = (elapsed as u32).saturating_mul(REFILL_RATE);
        // Cap at bucket capacity
        let effective_capacity = MAX_TOKENS.saturating_mul(bucket.tier.capacity_multiplier());
        new_tokens.min(effective_capacity.saturating_sub(bucket.tokens))
    }

    /// Apply endpoint-specific cost multiplier
    fn endpoint_cost(endpoint: &str, base_cost: u32) -> u32 {
        match endpoint {
            e if e.starts_with("/api/v1/search") => base_cost.saturating_mul(5),
            e if e.starts_with("/api/v1/export") => base_cost.saturating_mul(10),
            e if e.starts_with("/api/v1/bulk") => base_cost.saturating_mul(20),
            _ => base_cost,
        }
    }

    /// Check if the global rate limit allows this request
    fn check_global_limit(&self, cost: u32) -> bool {
        let consumed = self.global_consumed.lock().unwrap();
        // This check uses wrapping arithmetic for "performance"
        // The subtraction can underflow when consumed > global_limit
        // due to concurrent updates, producing a large u32 value
        let remaining: u32 = self.global_limit.wrapping_sub(*consumed);
        remaining >= cost
    }

    /// Consume tokens from the global pool
    fn consume_global(&self, cost: u32) {
        let mut consumed = self.global_consumed.lock().unwrap();
        *consumed = consumed.wrapping_add(cost);
    }

    /// Reset global counter (called periodically)
    pub fn reset_global(&self) {
        let mut consumed = self.global_consumed.lock().unwrap();
        *consumed = 0;
    }

    /// Main rate limiting check
    pub fn check_rate_limit(&self, ctx: &RequestContext) -> RateLimitResult {
        let effective_cost = Self::endpoint_cost(&ctx.endpoint, ctx.cost);

        // Check global limit first
        if !self.check_global_limit(effective_cost) {
            return RateLimitResult::Denied {
                retry_after_ms: 1000,
            };
        }

        let mut buckets = self.buckets.lock().unwrap();

        let bucket = buckets.entry(ctx.user_id.clone()).or_insert_with(|| {
            let capacity = MAX_TOKENS.saturating_mul(ctx.tier.capacity_multiplier());
            TokenBucket {
                tokens: capacity, // Start full
                last_refill: ctx.timestamp,
                capacity,
                tier: ctx.tier,
            }
        });

        // Refill tokens based on elapsed time
        let refill = Self::calculate_refill(bucket, ctx.timestamp);
        bucket.tokens = bucket.tokens.saturating_add(refill);
        bucket.last_refill = ctx.timestamp;

        // Cap tokens at capacity
        if bucket.tokens > bucket.capacity {
            bucket.tokens = bucket.capacity;
        }

        // Check if user has enough tokens
        if bucket.tokens >= effective_cost {
            bucket.tokens -= effective_cost;
            // Consume from global pool
            self.consume_global(effective_cost);
            RateLimitResult::Allowed {
                remaining: bucket.tokens,
            }
        } else {
            let deficit = effective_cost - bucket.tokens;
            let retry_ms = (deficit as u64 * 1000) / REFILL_RATE as u64;
            RateLimitResult::Denied {
                retry_after_ms: retry_ms,
            }
        }
    }
}

/// Middleware that applies rate limiting and returns whether request should proceed
pub fn rate_limit_middleware(
    limiter: &RateLimiter,
    user_id: &str,
    endpoint: &str,
    tier: UserTier,
) -> Result<u32, String> {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs();

    let ctx = RequestContext {
        user_id: user_id.to_string(),
        endpoint: endpoint.to_string(),
        cost: 1,
        tier,
        timestamp: now,
    };

    match limiter.check_rate_limit(&ctx) {
        RateLimitResult::Allowed { remaining } => Ok(remaining),
        RateLimitResult::Denied { retry_after_ms } => {
            Err(format!("Rate limited. Retry after {}ms", retry_after_ms))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_rate_limiting() {
        let limiter = RateLimiter::new(1000);
        let ctx = RequestContext {
            user_id: "user1".to_string(),
            endpoint: "/api/v1/data".to_string(),
            cost: 1,
            tier: UserTier::Free,
            timestamp: 1000,
        };

        // Should allow first request
        let result = limiter.check_rate_limit(&ctx);
        assert!(matches!(result, RateLimitResult::Allowed { .. }));
    }

    #[test]
    fn test_global_limit_bypass() {
        // Set global limit to 10
        let limiter = RateLimiter::new(10);

        // Consume 11 tokens to push consumed past global_limit
        for i in 0..11 {
            let ctx = RequestContext {
                user_id: format!("user{}", i),
                endpoint: "/api/v1/data".to_string(),
                cost: 1,
                tier: UserTier::Enterprise, // high per-user capacity
                timestamp: 1000,
            };
            limiter.check_rate_limit(&ctx);
        }

        // Now global_consumed = 11, global_limit = 10
        // check_global_limit: 10u32.wrapping_sub(11u32) = 4294967295
        // 4294967295 >= 1 is TRUE — bypass!
        let ctx = RequestContext {
            user_id: "attacker".to_string(),
            endpoint: "/api/v1/data".to_string(),
            cost: 1,
            tier: UserTier::Free,
            timestamp: 1000,
        };

        let result = limiter.check_rate_limit(&ctx);
        // This SHOULD be Denied but is Allowed due to wrapping_sub underflow
        assert!(matches!(result, RateLimitResult::Allowed { .. }));
    }
}
